mapper.select:
SELECT MDFM_CLS_CD AS recordId, MDFM_ID AS mdfmId, MDFM_FOM_SEQ AS mdfmFomSeq, MDFM_SCTN_SEQ AS sectionId, MDFM_CPEM_ID AS id, UPR_MDFM_CPEM_ID AS parentId, CASE WHEN MDFM_ELMT_CLS_CD = 'E' THEN 'ENTITY' WHEN MDFM_ELMT_CLS_CD = 'A' THEN 'ATTRIBUTE' WHEN MDFM_ELMT_CLS_CD = 'V' THEN 'VALUE' ELSE 'UNKNOWN' END AS classType, CASE WHEN ELMT_CCLS_CD = '1' THEN 'LABEL' WHEN ELMT_CCLS_CD = '2' THEN 'TEXT_BOX' WHEN ELMT_CCLS_CD = '3' THEN 'RICH_TEXT_BOX' WHEN ELMT_CCLS_CD = '4' THEN 'COMBO_BOX' WHEN ELMT_CCLS_CD = '5' THEN 'CHECK_BOX' WHEN ELMT_CCLS_CD = '6' THEN 'RADIO_BUTTON' WHEN ELMT_CCLS_CD = '7' THEN 'IMAGE' WHEN ELMT_CCLS_CD = '8' THEN 'NUMERIC_TEXT_BOX' WHEN ELMT_CCLS_CD = '9' THEN 'DATE_TEXT_BOX' WHEN ELMT_CCLS_CD = '12' THEN 'DATA_GRID' ELSE 'UNKNOWN' END AS controlType, NULL as maskingType, ISNULL(MDFM_CPEM_CNTE, ELMT_BSC_CNTE) AS content, ELMT_BSC_CNTE AS "desc", LSH_DTM AS loadDtm FROM ods.S_MRFMFCID
WHERE LSH_DTM::DATE >= #{startDate}::DATE AND LSH_DTM::DATE <= #{endDate}::DATE AND MDFM_CLS_CD = #{recordId}
ORDER BY MDFM_CLS_CD, MDFM_ID, MDFM_FOM_SEQ, MDFM_SCTN_SEQ, MDFM_CPEM_ID, UPR_MDFM_CPEM_ID
